#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>

bool read_int(const char *prompt, long min, long max, long *out) {
    char line[64];
    for (;;) {
        printf("%s", prompt);
        if (fgets(line, sizeof line, stdin) == NULL) return false;  /* EOF or error. */
        if (strchr(line, '\n') == NULL && !feof(stdin)) {           /* too long. */
            int ch;
            while ((ch = getchar()) != '\n' && ch != EOF) {}        /* discard rest. */
            puts("Too long, try again.");
            continue;
        }
        char *end;
        errno = 0;
        long v = strtol(line, &end, 10);
        while (*end == ' ' || *end == '\t') end++;                  /* allow spaces. */
        if (end == line || (*end != '\n' && *end != '\0')) { puts("Not a whole number."); continue; }
        if (errno == ERANGE || v < min || v > max) { puts("Out of range."); continue; }
        *out = v;
        return true;
    }
}
